+    );
+    assert!(
+        screen.contains("T42 model"),
+        "original Home choice remains visible"
+    );
+    pty.send(&vec![0x7f; 512]);
+    for project in [
+        fixture.project_b(),
+        fixture.project_a(),
+        fixture.project_b(),
