+        // configured additional skills/MCP resources.
+        assert_eq!(journal_counts(&fixture), (0, 0, 0, 0, 0));
+    }
+    assert!(fixture.requests.lock().unwrap().is_empty());
+    pty.send(b"first on B\r");
